WORK = os.environ.get("SOAT_WORK") or ("/mnt/data" if os.path.isdir("/mnt/data") else os.getcwd())
SEV = ["Priority", "Major", "Minor"]
CAUSE = ["Facility", "Administrative"]
DUE = {"Priority": 1, "Major": 7, "Minor": 30}
PAL = [("#FF2D2D", "#FFFFFF"), ("#FFD60A", "#111111"), ("#00E0FF", "#111111"), ("#FF4FD8", "#111111"),
       ("#7CFF4F", "#111111"), ("#FF9500", "#111111"), ("#FFFFFF", "#111111"), ("#4D8DFF", "#FFFFFF")]
INK, MUTED, RED, BLUE, RULE_LINE, BAND = "#14191C", "#55626A", "#C8102E", "#00558F", "#D3DAD9", "#EEF1F0"

