KINDS = {"violation": "Vi phạm", "hazard": "Mối nguy tiềm ẩn"}
# Ô ảnh mặc định: cột rộng 36 (khoảng 189 pt trên Excel Windows, 216 pt trên Excel Mac), dòng cao 150 pt.
