# ---------- Trạng thái ----------
def _state_path():
    return os.path.join(WORK, "soat_ehs_state.json")


def _dir():
    d = os.path.join(WORK, "soat_ehs")
    os.makedirs(d, exist_ok=True)
    return d


def _load():
    if os.path.exists(_state_path()):
        with open(_state_path(), encoding="utf-8") as f:
            return json.load(f)
    return {"meta": {"subsidiary": "SEV/T", "vendor": "", "auditor": "", "date": datetime.date.today().isoformat()}, "photos": []}


def _save(st):
    tmp = _state_path() + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(st, f, ensure_ascii=False)
    os.replace(tmp, _state_path())


def _iso(d):
    d = str(d).strip()
    m = re.match(r"^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$", d)
    return "%04d-%02d-%02d" % (int(m.group(3)), int(m.group(2)), int(m.group(1))) if m else d


def _vn(iso):
    return "/".join(reversed(iso.split("-"))) if iso else ""


def _numbered(st):
    for pi, p in enumerate(st["photos"], 1):
        for k, f in enumerate(p["findings"], 1):
            yield pi, k, p, f


def _find(st, ref):
    m = re.match(r"^\s*(\d+)\s*[.,/:-]\s*(\d+)\s*$", str(ref))
    if not m:
        raise ValueError('Số lỗi có dạng "ảnh.lỗi", ví dụ "3.2"')
    pi, k = int(m.group(1)), int(m.group(2))
    if not 1 <= pi <= len(st["photos"]) or not 1 <= k <= len(st["photos"][pi - 1]["findings"]):
        raise ValueError("Không có lỗi %s" % ref)
    p = st["photos"][pi - 1]
    return pi, p, p["findings"][k - 1]


# ---------- Hình học ----------
def _size(b):
    return b["w"] * b["h"]


def _union(a, b):
    x, y = min(a["x"], b["x"]), min(a["y"], b["y"])
    return {"x": x, "y": y, "w": max(a["x"] + a["w"], b["x"] + b["w"]) - x, "h": max(a["y"] + a["h"], b["y"] + b["h"]) - y}


def _inter(a, b):
    return max(0, min(a["x"] + a["w"], b["x"] + b["w"]) - max(a["x"], b["x"])) * max(0, min(a["y"] + a["h"], b["y"] + b["h"]) - max(a["y"], b["y"]))


def _iou(a, b):
    i = _inter(a, b)
    return i / ((_size(a) + _size(b) - i) or 1)


def _box(b):
    try:
        v = [float(x) for x in list(b)[:4]]
        assert len(v) == 4
    except Exception:
        return None
    c = lambda t: min(1.0, max(0.0, t / 1000.0))
    x, y = c(min(v[0], v[2])), c(min(v[1], v[3]))
    w, h = c(max(v[0], v[2])) - x, c(max(v[1], v[3])) - y
    return {"x": x, "y": y, "w": w, "h": h} if w > 0.01 and h > 0.01 else None


def cells_to_box(cells):
    """Đổi ô lưới, ví dụ "C3:E5" hoặc "D4", thành vùng trên ảnh."""
    m = re.findall(r"([A-Ja-j])\s*(10|[1-9])", str(cells))
    if not m:
        raise ValueError('Ô lưới phải có dạng "C3:E5"')
    cols = [ord(a.upper()) - 65 for a, _ in m]
    rows = [int(b) - 1 for _, b in m]
    return {"x": min(cols) / 10, "y": min(rows) / 10, "w": (max(cols) - min(cols) + 1) / 10, "h": (max(rows) - min(rows) + 1) / 10}


def _trim(findings):
    rects = sorted([f["s"] for f in findings], key=_size)
    gap = 0.004
    for _ in range(2):
        for i, a in enumerate(rects):
            for b in rects[i + 1:]:
                if not _inter(a, b):
                    continue
                opts = [
                    {"x": a["x"] + a["w"] + gap, "y": b["y"], "w": b["x"] + b["w"] - a["x"] - a["w"] - gap, "h": b["h"]},
                    {"x": b["x"], "y": b["y"], "w": a["x"] - b["x"] - gap, "h": b["h"]},
                    {"x": b["x"], "y": a["y"] + a["h"] + gap, "w": b["w"], "h": b["y"] + b["h"] - a["y"] - a["h"] - gap},
                    {"x": b["x"], "y": b["y"], "w": b["w"], "h": a["y"] - b["y"] - gap}]
                opts = sorted([o for o in opts if o["w"] > 0.02 and o["h"] > 0.02], key=_size, reverse=True)
                if opts and _size(opts[0]) >= 0.6 * _size(b):
                    b.update(opts[0])


def _sentence(t):
    t = (t or "").strip()
    return t + "." if t and t[-1] not in ".!?;:" else t


def _join(a, b):
    return "%s %s" % (_sentence(a), _sentence(b)) if a and b and a != b else (a or b or "")


def _merge_into(o, f):
    o["title_vi"] = "%s; %s%s" % (o["title_vi"], f["title_vi"][:1].lower(), f["title_vi"][1:])
    if f["title_en"]:
        o["title_en"] = "%s; %s%s" % (o["title_en"], f["title_en"][:1].lower(), f["title_en"][1:]) if o["title_en"] else f["title_en"]
    for k in ("ev", "fix_now", "fix_root", "plan_en"):
        o[k] = _join(o[k], f[k])
    rank = lambda v: SEV.index(v) if v in SEV else 9
    o["sev"] = f["sev"] if rank(f["sev"]) < rank(o["sev"]) else o["sev"]
    o["mand"] = o["mand"] or f["mand"]
    o["kind"] = "violation" if "violation" in (o.get("kind"), f.get("kind")) else "hazard"
    o["cause"] = "Facility" if "Facility" in (o["cause"], f["cause"]) else o["cause"]
    o["law"] = " | ".join(dict.fromkeys([x for x in o["law"].split(" | ") + f["law"].split(" | ") if x]))
    o["s"] = _union(o["s"], f["s"])
    if o["conf"] is not None and f["conf"] is not None:
        o["conf"] = min(o["conf"], f["conf"])


def _tidy(findings):
    out = []
    for f in findings:
        hit = None
        for o in out:
            b, c = f["s"], o["s"]
            i, m = _inter(b, c), min(_size(b), _size(c))
            if o["code"] and o["code"] == f["code"] and (_iou(b, c) >= 0.45 or (i / m >= 0.75 and m / max(_size(b), _size(c)) >= 0.4)):
                hit = o
                break
        if hit:
            _merge_into(hit, f)
        else:
            out.append(f)
    _trim(out)
    return out


# ---------- Vẽ ----------
_FONTS = {}


def _font(size, bold=False):
    key = (round(size), bold)
    if key in _FONTS:
        return _FONTS[key]
    names = (["DejaVuSans-Bold.ttf", "Arial Bold.ttf", "LiberationSans-Bold.ttf"] if bold else ["DejaVuSans.ttf", "Arial.ttf", "LiberationSans-Regular.ttf"])
    dirs = ["", "/usr/share/fonts/truetype/dejavu/", "/usr/share/fonts/dejavu/", "/usr/share/fonts/truetype/liberation/", "/System/Library/Fonts/Supplemental/", "/Library/Fonts/"]
    try:
        import matplotlib
        dirs.append(os.path.join(matplotlib.get_data_path(), "fonts", "ttf") + os.sep)
    except Exception:
        pass
    for n in names:
        for d in dirs:
            try:
                _FONTS[key] = ImageFont.truetype(d + n, key[0])
                return _FONTS[key]
            except Exception:
                continue
    raise RuntimeError("Không tìm thấy phông chữ có tiếng Việt")


def _nfc(t):
    return unicodedata.normalize("NFC", str(t))


def _regions(items):
    out = []
    for n, f in items:
        b = f["s"]
        g = next((r for r in out if _iou(r["b"], b) >= 0.6), None)
        if g:
            g["items"].append((n, f))
            g["b"] = _union(g["b"], b)
        else:
            out.append({"b": dict(b), "items": [(n, f)]})
    for i, r in enumerate(out):
        r["c"] = PAL[i % len(PAL)]
    return out


def _touch(x, y, rx, ry, q):
    l, e, t, u = x - rx, x + rx, y - ry, y + ry
    if e < q[0] or l > q[2] or u < q[1] or t > q[3]:
        return 0
    return 2 if l > q[0] and e < q[2] and t > q[1] and u < q[3] else 1


def _place(rs, px, W, H, r):
    d = r * 1.5
    placed, res = [], [None] * len(rs)
    small = lambda q: min(q[2] - q[0], q[3] - q[1]) < r * 4
    for i in sorted(range(len(rs)), key=lambda k: (px[k][2] - px[k][0]) * (px[k][3] - px[k][1])):
        a, b, c, e = px[i]
        hw, cx, cy = (len(rs[i]["items"]) - 1) * 1.3 * r, (a + c) / 2, (b + e) / 2
        best = None
        cand = [(a, b, 0), (c, b, 0), (a, e, 0), (c, e, 0), (cx, b, 1), (cx, e, 1), (a, cy, 1), (c, cy, 1), (cx, b - d, 2), (cx, e + d, 2),
                (a - d - hw, cy, 2), (c + d + hw, cy, 2), (a - d, b - d, 3), (c + d, b - d, 3), (a - d, e + d, 3), (c + d, e + d, 3),
                (a + d + hw, b + d, 4), (c - d - hw, b + d, 4), (a + d + hw, e - d, 4), (c - d - hw, e - d, 4)]
        for x, y, base in cand:
            fx = min(W - r * 1.5 - hw, max(r * 1.5 + hw, x))
            fy = min(H - r * 1.5, max(r * 1.5, y))
            cost = base + (6 if ((fx - x) ** 2 + (fy - y) ** 2) ** 0.5 > r * 0.5 else 0)
            if small(px[i]) and _touch(fx, fy, r * 1.2 + hw, r * 1.2, px[i]):
                cost += 30
            for j, q in enumerate(px):
                if j != i:
                    t = _touch(fx, fy, r * 1.3 + hw, r * 1.3, q)
                    if t:
                        cost += 70 if small(q) else (12 if t == 2 else 35)
            for k in placed:
                if abs(fx - k[0]) < k[2] + hw + r * 2.8 and abs(fy - k[1]) < r * 2.8:
                    cost += 1000
            if best is None or cost < best[3]:
                best = (fx, fy, hw, cost)
        placed.append(best)
        res[i] = best
    return res


def _badge(d, n, sev, x, y, r, c):
    def shape(rad, fill):
        if sev == "Priority":
            import math
            R = rad * 1.15
            d.polygon([(x + R * math.cos(0.3927 + i * 0.7854), y + R * math.sin(0.3927 + i * 0.7854)) for i in range(8)], fill=fill)
        elif sev == "Major":
            R = rad * 1.35
            d.polygon([(x, y - R), (x + R, y), (x, y + R), (x - R, y)], fill=fill)
        else:
            d.ellipse([x - rad, y - rad, x + rad, y + rad], fill=fill)
    shape(r * 1.14, "#111111")
    shape(r, c[0])
    d.text((x, y), str(n), font=_font(r * 1.15, True), fill=c[1], anchor="mm")


def _marks(im, items, lw, r):
    W, H = im.size
    S = 2
    ov = Image.new("RGBA", (W * S, H * S), (0, 0, 0, 0))
    d = ImageDraw.Draw(ov)
    rs = _regions(items)
    px = [[g["b"]["x"] * W * S, g["b"]["y"] * H * S, (g["b"]["x"] + g["b"]["w"]) * W * S, (g["b"]["y"] + g["b"]["h"]) * H * S] for g in rs]
    for g, q in zip(rs, px):
        q2 = [q[0], q[1], max(q[0] + 1, min(q[2], W * S - 1)), max(q[1] + 1, min(q[3], H * S - 1))]
        d.rectangle(q2, outline=(0, 0, 0, 150), width=int(lw * S * 2))
        d.rectangle(q2, outline=g["c"][0], width=int(lw * S))
    for g, p in zip(rs, _place(rs, px, W * S, H * S, r * S)):
        for k, (n, f) in enumerate(g["items"]):
            _badge(d, n, f["sev"], p[0] - p[2] + k * 2.6 * r * S, p[1], r * S, g["c"])
    return Image.alpha_composite(im.convert("RGBA"), ov.resize((W, H), Image.LANCZOS)).convert("RGB")


def _grid(im):
    W, H = im.size
    ov = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    d = ImageDraw.Draw(ov)
    for i in range(1, 10):
        x, y = i * W // 10, i * H // 10
        d.line([(x, 0), (x, H)], fill=(255, 255, 255, 110), width=1)
        d.line([(0, y), (W, y)], fill=(255, 255, 255, 110), width=1)
    f = _font(max(12, W // 75), True)
    for i in range(10):
        cx, cy = (i + 0.5) * W / 10, (i + 0.5) * H / 10
        for (tx, ty, t) in ((cx, f.size * 0.8, "ABCDEFGHIJ"[i]), (f.size * 0.9, cy, str(i + 1))):
            d.rectangle([tx - f.size * 0.75, ty - f.size * 0.7, tx + f.size * 0.75, ty + f.size * 0.7], fill=(0, 0, 0, 170))
            d.text((tx, ty), t, font=f, fill=(255, 255, 255, 255), anchor="mm")
    return Image.alpha_composite(im.convert("RGBA"), ov).convert("RGB")


def _photo(p):
    return Image.open(p["file"]).convert("RGB")


def _fit(im, w, h):
    k = min(w / im.width, h / im.height)
    return im.resize((max(1, round(im.width * k)), max(1, round(im.height * k))), Image.LANCZOS)


def _wrap(text, font, width):
    out = []
    for para in _nfc(text).split("\n"):
        line = ""
        for word in para.split():
            t = (line + " " + word) if line else word
            if font.getlength(t) > width and line:
                out.append(line)
                line = word
            else:
                line = t
        if line:
            out.append(line)
    return out


def _report(st, p, items):
    """Ảnh báo cáo: dòng đầu ghi công ty và ngày; dưới ảnh là danh sách lỗi đánh số đúng như trên ảnh."""
    W, pad = 1800, 56
    ph = _fit(_photo(p), W - 2 * pad, 1320)
    ph = _marks(ph, items, max(3, ph.width / 440), max(16, min(24, ph.width / 56)))
    ft, fe, fl, fv = _font(30, True), _font(25), _font(26), _font(26, True)
    tw = W - 2 * pad - 70
    colors = {}
    for g in _regions(items):
        for n, _ in g["items"]:
            colors[n] = g["c"]
    blocks = []
    for n, f in items:
        tl = _wrap(f["title_vi"], ft, tw)
        ev = (f["ev"] or "").strip()
        el = _wrap(ev, fe, tw) if ev and ev != f["title_vi"].strip() else []
        blocks.append((n, f, tl, el, max(len(tl) * 41 + (8 + len(el) * 35 if el else 0), 48) + 30))
    head = 84
    H = head + ph.height + 34 + sum(b[-1] for b in blocks) + 24
    im = Image.new("RGB", (W, H), "#FFFFFF")
    d = ImageDraw.Draw(im)
    m, x = st["meta"], pad
    for lab, val in (("Công ty", m["vendor"]), ("Ngày", _vn(m["date"]))):
        if not val:
            continue
        d.text((x, 30), lab + ": ", font=fl, fill=MUTED)
        x += fl.getlength(lab + ": ")
        d.text((x, 30), _nfc(val), font=fv, fill=INK)
        x += fv.getlength(_nfc(val)) + 48
    d.rectangle([pad, head, W - pad, head + ph.height], fill="#1A2125")
    im.paste(ph, ((W - ph.width) // 2, head))
    y = head + ph.height + 34
    ov = Image.new("RGBA", (W * 2, H * 2), (0, 0, 0, 0))
    od = ImageDraw.Draw(ov)
    for n, f, tl, el, hh in blocks:
        _badge(od, n, f["sev"], (pad + 24) * 2, (y + 18) * 2, 40, colors[n])
        ty = y
        for l in tl:
            d.text((pad + 70, ty), l, font=ft, fill=INK)
            ty += 41
        if el:
            ty += 8
            for l in el:
                d.text((pad + 70, ty), l, font=fe, fill="#3A464C")
                ty += 35
        y += hh
        d.line([(pad, y - 14), (W - pad, y - 14)], fill=RULE_LINE, width=2)
    return Image.alpha_composite(im.convert("RGBA"), ov.resize((W, H), Image.LANCZOS)).convert("RGB")


# ---------- Sổ kinh nghiệm: học từ quyết định của người đánh giá ----------
LTYPE = {"fix": "Đã sửa", "miss": "AI bỏ sót", "reject": "Không phải lỗi", "unclear": "Ảnh không đủ rõ"}
LESSON_FILE = "So-kinh-nghiem-EHS.json"
MAX_LESSONS = 300


def _lpath():
    return os.path.join(WORK, "soat_ehs_lessons.json")


def _ms():
    return int(datetime.datetime.now().timestamp() * 1000)


def _ok_lesson(x):
    return (isinstance(x, dict) and isinstance(x.get("id"), str) and x.get("t") in LTYPE and isinstance(x.get("title"), str)
            and isinstance(x.get("at"), (int, float)) and not isinstance(x.get("at"), bool))


def _lbook():
    try:
        with open(_lpath(), encoding="utf-8") as f:
            d = json.load(f)
        return {"items": [x for x in d.get("items", []) if _ok_lesson(x)], "mark": int(d.get("mark") or 0), "files": dict(d.get("files") or {})}
    except Exception:
        return {"items": [], "mark": 0, "files": {}}


def _lsave(b):
    b["items"].sort(key=lambda x: -x["at"])
    del b["items"][MAX_LESSONS:]
    tmp = _lpath() + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(b, f, ensure_ascii=False)
    os.replace(tmp, _lpath())


def _snap(f):
    return {"rule": f.get("rule") or "", "code": f.get("code") or "", "req": f.get("req") or "", "sev": f.get("sev") or "", "kind": f.get("kind") or "violation"}


def _fdesc(o):
    return ", ".join(x for x in ((o or {}).get("req") or (o or {}).get("code"), (o or {}).get("sev"), KINDS.get((o or {}).get("kind"))) if x)


def _words(t):
    return set(w for w in re.split(r"[^\w]+", _nfc(t).lower()) if len(w) > 2 and not w.isdigit() and "_" not in w)


def _ladd(x):
    """Ghi một kinh nghiệm. Trùng nội dung thì chỉ làm mới thời điểm để kinh nghiệm đó được ưu tiên."""
    b = _lbook()
    key = lambda y: (y["t"], _nfc(y["title"]).strip().lower(), json.dumps(y.get("from"), sort_keys=True), json.dumps(y.get("to"), sort_keys=True))
    k = key(x)
    for y in b["items"]:
        if key(y) == k:
            y["at"] = _ms()
            if x.get("area"):
                y["area"] = x["area"]
            _lsave(b)
            return False
    who = (_load()["meta"].get("auditor") or "").split(",")[0].strip()
    b["items"].insert(0, dict(x, id=os.urandom(8).hex(), at=_ms(), by=who))
    _lsave(b)
    return True


def _learn(p, f):
    """Ghi kinh nghiệm khi người đánh giá chốt một lỗi: AI đề xuất sai mã/mức độ/loại, hoặc AI bỏ sót."""
    if f.get("learned"):
        return ""
    f["learned"] = True
    title, now, a = f["title_vi"].strip(), _snap(f), f.get("ai0")
    if not title:
        return ""
    if f.get("src") == "ai" and a:
        if all(a.get(k) == now[k] for k in ("code", "req", "sev", "kind")):
            return ""
        new = _ladd({"t": "fix", "title": title, "area": p.get("area_vi", ""), "from": a, "to": now})
        return "%s: %s → %s" % ("Đã ghi vào sổ kinh nghiệm" if new else "Sổ kinh nghiệm đã có, đã củng cố", _fdesc(a), _fdesc(now))
    if f.get("src") == "manual":
        new = _ladd({"t": "miss", "title": title, "area": p.get("area_vi", ""), "to": now})
        return "Đã ghi vào sổ kinh nghiệm: AI bỏ sót lỗi này" if new else "Sổ kinh nghiệm đã có lỗi AI bỏ sót này, đã củng cố"
    return ""


def _lline(x):
    at = " (khu %s)" % x["area"] if x.get("area") else ""
    if x["t"] == "fix":
        return '- Đã sửa "%s"%s: AI đề xuất %s; người đánh giá chốt %s.' % (x["title"], at, _fdesc(x.get("from")), _fdesc(x.get("to")))
    if x["t"] == "miss":
        return '- AI bỏ sót "%s"%s (%s). Gặp tình huống tương tự phải báo lỗi này.' % (x["title"], at, _fdesc(x.get("to")))
    if x["t"] == "reject":
        return '- Không phải lỗi: "%s"%s. Không đề xuất lại khi tình huống tương tự.' % (x["title"], at)
    return '- Ảnh không đủ rõ để kết luận "%s"%s. Chỉ báo khi thấy rõ, nếu không thì ghi vào verify.' % (x["title"], at)


def lessons(context="", limit=14):
    """Kinh nghiệm từ người đánh giá liên quan nhất tới context (khu vực, mô tả cảnh). Đọc và áp dụng trước khi soát ảnh."""
    items = _lbook()["items"]
    if not items:
        return ""
    ctx = _words(context)
    pick = sorted(enumerate(items), key=lambda t: -(len(_words(t[1]["title"] + " " + (t[1].get("area") or "")) & ctx) * 3 - t[0] * 0.02))[:limit]
    return ("KINH NGHIỆM TỪ NGƯỜI ĐÁNH GIÁ (quyết định đã được xác nhận; áp dụng khi gặp tình huống tương tự, ưu tiên hơn mức gợi ý trong danh mục)\n"
            + "\n".join(_lline(x) for _, x in pick))


def lesson_book():
    """Toàn bộ sổ kinh nghiệm, mới nhất trước, đánh số để xem hoặc xóa."""
    items = _lbook()["items"]
    if not items:
        return "Sổ kinh nghiệm đang trống."
    out = []
    for i, x in enumerate(items, 1):
        d = "%s → %s" % (_fdesc(x.get("from")), _fdesc(x.get("to"))) if x["t"] == "fix" else _fdesc(x.get("to"))
        day = datetime.datetime.fromtimestamp(x["at"] / 1000).strftime("%d/%m/%Y")
        out.append("%d | %s | %s | %s" % (i, LTYPE[x["t"]], x["title"], " · ".join(v for v in (d, x.get("area"), x.get("by"), day) if v)))
    return "\n".join(out)


def forget_lesson(no):
    """Xóa kinh nghiệm số no theo lesson_book(), hoặc no="all" để xóa hết."""
    b = _lbook()
    if str(no).strip().lower() == "all":
        n, b["items"] = len(b["items"]), []
    else:
        i = int(no) - 1
        if not 0 <= i < len(b["items"]):
            raise ValueError("Không có kinh nghiệm số %s" % no)
        b["items"].pop(i)
        n = 1
    b["mark"] = 0
    _lsave(b)
    return "Đã xóa %d kinh nghiệm. Còn %d. Hãy xuất lại sổ bằng export_lessons() và thay file trong Project." % (n, len(b["items"]))


def export_lessons():
    """Xuất sổ kinh nghiệm ra So-kinh-nghiem-EHS.json. Thêm file này vào Project (thay file cũ) để các cuộc trò chuyện sau học được."""
    b = _lbook()
    path = os.path.join(WORK, LESSON_FILE)
    with open(path, "w", encoding="utf-8") as f:
        json.dump({"app": "soat-anh-ehs", "kind": "lessons", "v": 1, "items": b["items"]}, f, ensure_ascii=False, indent=1)
    b["mark"] = _ms()
    b["files"][os.path.abspath(path)] = _sha_file(path)
    _lsave(b)
    return dict(file=path, count=len(b["items"]))


def _new_lessons():
    b = _lbook()
    return sum(1 for x in b["items"] if x["at"] > b["mark"])


def _import_lessons(path):
    """Gộp sổ kinh nghiệm từ một file .json. Trả về số kinh nghiệm mới thêm."""
    with open(path, encoding="utf-8") as f:
        d = json.load(f)
    items = d.get("items") if isinstance(d, dict) else d
    if not isinstance(items, list):
        raise ValueError("File không phải sổ kinh nghiệm")
    b = _lbook()
    have = set(x["id"] for x in b["items"])
    n = 0
    for x in items:
        if _ok_lesson(x) and x["id"] not in have:
            b["items"].append({k: x[k] for k in ("id", "t", "title", "area", "from", "to", "at", "by") if k in x})
            have.add(x["id"])
            n += 1
    b["mark"] = max(b["mark"], max([x["at"] for x in b["items"]] + [0]))
    b["files"][os.path.abspath(path)] = _sha_file(path)
    _lsave(b)
    return n


def _use_lessons(area, fs, excluded):
    """Áp kinh nghiệm cho các đề xuất mới của AI. Trả về ghi chú để báo người dùng."""
    items = _lbook()["items"]
    notes = []
    for f in list(fs):
        w = _words(f["title_vi"])
        best = None
        for x in items:
            o = x.get("from") if x["t"] == "fix" else x.get("to")
            if x["t"] == "miss" or not o or not w:
                continue
            if not ((o.get("rule") and o.get("rule") == f.get("rule")) or (o.get("req") and o.get("req") == f.get("req"))):
                continue
            xw = _words(x["title"])
            sim = len(w & xw) / (len(w | xw) or 1)
            if sim >= 0.6 and (best is None or sim > best[0]):
                best = (sim, x)
        if not best:
            continue
        x = best[1]
        if x["t"] == "fix":
            t = x["to"]
            if t.get("rule") in RULES and t["rule"] != f.get("rule"):
                _resolve(f, {"rule": t["rule"]})
            elif t.get("code") and t["code"] != f.get("code"):
                notes.append('"%s": người đánh giá từng chốt %s, cần đổi mã bằng update' % (f["title_vi"], _fdesc(t)))
            if t.get("sev") in SEV:
                f["sev"] = t["sev"]
            if t.get("kind") in KINDS:
                f["kind"] = t["kind"]
            notes.append('Đã áp dụng kinh nghiệm cho "%s": %s → %s' % (f["title_vi"], _fdesc(x.get("from")), _fdesc(_snap(f))))
        elif x["t"] == "reject":
            fs.remove(f)
            excluded.append("%s: người đánh giá từng kết luận không phải lỗi trong tình huống tương tự" % f["title_vi"])
        else:
            notes.append('"%s": người đánh giá từng đánh giá ảnh tương tự không đủ rõ. Chỉ giữ nếu ảnh này thấy rõ' % f["title_vi"])
    return notes


# ---------- Đọc và ghi file Excel bằng thư viện chuẩn, giữ nguyên định dạng ----------
_NM = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
_NR = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}"
_NP = "{http://schemas.openxmlformats.org/package/2006/relationships}"
_ROW = re.compile(r"<((?:[\w.-]+:)?)row(?=[\s/>])([^>]*?)(?:(/>)|>(.*?)</\1row>)", re.S)
_CELL = re.compile(r"<((?:[\w.-]+:)?)c(?=[\s/>])([^>]*?)(?:/>|>(.*?)</\1c>)", re.S)


def _sha_file(path):
    with open(path, "rb") as f:
        return hashlib.sha1(f.read()).hexdigest()


def _norm(s):
    return re.sub(r"\s+", " ", _nfc("" if s is None else s)).strip().lower()


def _coln(ref):
    n = 0
    for ch in re.sub(r"[^A-Z]", "", ref):
        n = n * 26 + ord(ch) - 64
    return n


def _istext(node):
    if node is None:
        return ""
    ts = node.findall(_NM + "t") + [t for r in node.findall(_NM + "r") for t in r.findall(_NM + "t")]
    return "".join(t.text or "" for t in ts)


def _xcell(p, ref, attrs, kind, v):
    a = ' r="%s"%s' % (ref, re.sub(r'\s+(?:r|t|cm|vm)="[^"]*"', "", attrs).rstrip())
    if v is None or v == "":
        return "<%sc%s/>" % (p, a)
    if kind == "n":
        return "<%sc%s><%sv>%s</%sv></%sc>" % (p, a, p, v, p, p)
    return '<%sc%s t="inlineStr"><%sis><%st xml:space="preserve">%s</%st></%sis></%sc>' % (p, a, p, p, _esc(v), p, p, p)


class _Sheet:
    def __init__(self, xml, ss):
        self.xml, self.v, self.f, self.rows, self.edits = xml, {}, {}, {}, {}
        for row in ET.fromstring(xml.encode("utf-8")).iter(_NM + "row"):
            if not row.get("r"):
                continue
            refs = []
            for c in row.findall(_NM + "c"):
                ref = c.get("r")
                if not ref:
                    continue
                refs.append(ref)
                t, v = c.get("t"), c.find(_NM + "v")
                if t == "s":
                    self.v[ref] = ss[int(v.text)] if v is not None and (v.text or "").isdigit() and int(v.text) < len(ss) else ""
                elif t == "inlineStr":
                    self.v[ref] = _istext(c.find(_NM + "is"))
                else:
                    self.v[ref] = v.text or "" if v is not None else ""
                fe = c.find(_NM + "f")
                if fe is not None and fe.text:
                    self.f[ref] = fe.text
            self.rows[int(row.get("r"))] = refs
        self.nums = sorted(self.rows)

    def get(self, col, n):
        return self.v.get("%s%d" % (col, n), "") if col else ""

    def formula(self, col, n):
        return self.f.get("%s%d" % (col, n), "") if col else ""

    def header(self, first):
        """Tìm dòng tiêu đề trong 15 dòng đầu. Trả về (số dòng, hàm tìm cột theo tên tiêu đề)."""
        for n in self.nums[:15]:
            m = {}
            for ref in self.rows[n]:
                m[_norm(self.v.get(ref, ""))] = re.sub(r"\d+", "", ref)
            if _norm(first) in m:
                return n, (lambda k, m=m: next((c for key, c in m.items() if key.startswith(_norm(k))), None))
        return None

    def put(self, col, n, v, num=False):
        if col and n in self.rows:
            self.edits["%s%d" % (col, n)] = ("n" if num else "s", v)

    def dump(self):
        if not self.edits:
            return self.xml
        by = {}
        for ref, e in self.edits.items():
            by.setdefault(int(re.sub(r"\D", "", ref)), {})[ref] = e

        def row_sub(m):
            p, attrs, inner = m.group(1), m.group(2), m.group(4) or ""
            rn = re.search(r'\br="(\d+)"', attrs)
            if not rn or int(rn.group(1)) not in by:
                return m.group(0)
            ed = dict(by[int(rn.group(1))])

            def cell_sub(cm):
                r = re.search(r'\br="([A-Z]+\d+)"', cm.group(2))
                if not r or r.group(1) not in ed:
                    return cm.group(0)
                return _xcell(cm.group(1), r.group(1), cm.group(2), *ed.pop(r.group(1)))
            inner = _CELL.sub(cell_sub, inner)
            for ref in sorted(ed, key=_coln):
                cells = list(_CELL.finditer(inner))
                pos = next((c.start() for c in cells if _coln(re.search(r'\br="([A-Z]+)', c.group(2)).group(1)) > _coln(ref)), None)
                if pos is None:
                    pos = cells[-1].end() if cells else 0
                inner = inner[:pos] + _xcell(p, ref, "", *ed[ref]) + inner[pos:]
            return "<%srow%s>%s</%srow>" % (p, attrs.rstrip() if m.group(3) else attrs, inner, p)
        return _ROW.sub(row_sub, self.xml)


class _Book:
    def __init__(self, data):
        try:
            z = zipfile.ZipFile(io.BytesIO(data))
            self.names = [i.filename for i in z.infolist() if not i.is_dir()]
            self.parts = {n: z.read(n) for n in self.names}
            wb = ET.fromstring(self.parts["xl/workbook.xml"])
            rels = ET.fromstring(self.parts["xl/_rels/workbook.xml.rels"])
        except Exception:
            raise ValueError("File không phải sổ Excel .xlsx hợp lệ")
        path = lambda t: t[1:] if t.startswith("/") else "xl/" + re.sub(r"^\./", "", t)
        rel, ssp = {}, ""
        for r in rels.iter(_NP + "Relationship"):
            rel[r.get("Id")] = path(r.get("Target", ""))
            if r.get("Type", "").endswith("/sharedStrings"):
                ssp = path(r.get("Target", ""))
        self.sheets = {_nfc(s.get("name")): rel.get(s.get(_NR + "id")) for s in wb.iter(_NM + "sheet")}
        self.ss = [_istext(si) for si in ET.fromstring(self.parts[ssp]).iter(_NM + "si")] if ssp in self.parts else []
        self.cache = {}

    def sheet(self, name):
        p = self.sheets.get(_nfc(name))
        if not p or p not in self.parts:
            return None
        if p not in self.cache:
            self.cache[p] = _Sheet(self.parts[p].decode("utf-8"), self.ss)
        return self.cache[p]

    def save(self):
        for p, sh in self.cache.items():
            if sh.edits:
                self.parts[p] = sh.dump().encode("utf-8")
        wb = self.parts["xl/workbook.xml"].decode("utf-8")
        m = re.search(r"<((?:[\w.-]+:)?)calcPr(?=[\s/>])([^>]*?)(/?)>", wb)
        if m:
            attrs = re.sub(r'\s+fullCalcOnLoad="[^"]*"', "", m.group(2)).rstrip()
            wb = wb[:m.start()] + '<%scalcPr%s fullCalcOnLoad="1"%s>' % (m.group(1), attrs, m.group(3)) + wb[m.end():]
        else:
            p = re.search(r"<((?:[\w.-]+:)?)workbook(?=[\s>])", wb).group(1)
            nxt = re.search(r"<%s(?:oleSize|customWorkbookViews|pivotCaches|smartTagPr|smartTagTypes|webPublishing|fileRecoveryPr|webPublishObjects|extLst)(?=[\s/>])" % re.escape(p), wb)
            k = nxt.start() if nxt else wb.rindex("</%sworkbook>" % p)
            wb = wb[:k] + '<%scalcPr fullCalcOnLoad="1"/>' % p + wb[k:]
        self.parts["xl/workbook.xml"] = wb.encode("utf-8")
        out = io.BytesIO()
        with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
            for n in self.names:
                z.writestr(n, self.parts[n])
        return out.getvalue()


# ---------- File RBA Guider: nạp bản mới, tự cập nhật danh mục ----------
def _parse_guider(data):
    bk = _Book(data)
    G, L, T, O = bk.sheet("Guider chi tiết"), bk.sheet("Căn cứ pháp lý"), bk.sheet("Thang điểm"), bk.sheet("Tổng quan")
    if not G or not L:
        raise ValueError('Không thấy sheet "Guider chi tiết" hoặc "Căn cứ pháp lý" trong file')
    gh, lh = G.header("ID yêu cầu"), L.header("Mã RBA")
    if not gh or not lh:
        raise ValueError('Không nhận ra dòng tiêu đề của sheet "Guider chi tiết" hoặc "Căn cứ pháp lý"')
    (gr, gc), (lr, lc) = gh, lh
    codes, n_req, n_law = {}, 0, 0
    for n in G.nums:
        if n <= gr:
            continue
        qid, code = G.get(gc("id yêu cầu"), n).strip(), G.get(gc("mã hạng mục"), n).strip()
        if not re.match(r"^[A-Z]{2}\d{3}-\d{2}$", qid) or not re.match(r"^[A-Z]{2}\d{3}$", code):
            continue
        c = codes.setdefault(code, {"g": G.get(gc("nhóm hệ thống"), n).strip(), "t": G.get(gc("tiêu đề"), n).strip(), "s": {}, "r": [], "l": []})
        c["r"].append([qid, re.sub(r"\s+", " ", re.sub(r"^\s*-\s*", "", G.get(gc("nội dung yêu cầu"), n))).strip()])
        n_req += 1
    for n in L.nums:
        if n <= lr:
            continue
        code, it = L.get(lc("mã rba"), n).strip(), L.get(lc("hạng mục"), n).strip()
        if code not in codes or not it:
            continue
        law = L.get(lc("căn cứ pháp lý rà soát"), n).strip() or L.get(lc("căn cứ ghi nhận"), n).strip()
        codes[code]["l"].append([it, law])
        n_law += 1
    th = T.header("Audit ID") if T else None
    if th:
        tr, tc = th
        lv = {"conformance": "C", "minor": "Mi", "major": "Ma", "priority": "P"}
        for n in T.nums:
            if n <= tr:
                continue
            code, k = T.get(tc("audit id"), n).strip(), lv.get(_norm(T.get(tc("mức đánh giá"), n)))
            try:
                v = float(T.get(tc("điểm"), n))
            except ValueError:
                continue
            if code in codes and k and k not in codes[code]["s"]:
                codes[code]["s"][k] = int(v) if v == int(v) else v
    ver = date = ""
    for n in (O.nums[:12] if O else []):
        for col in "ABC":
            t = O.get(col, n)
            a = re.search(r"GUIDER\s+([\d.]+)", t, re.I)
            b = re.search(r"pháp lý[^0-9]*(\d{1,2}/\d{1,2}/\d{4})", t, re.I)
            ver = ver or (a.group(1).rstrip(".") if a else "")
            date = date or (b.group(1) if b else "")
    if not n_req:
        raise ValueError('Sheet "Guider chi tiết" không có ID yêu cầu nào dạng BH101-01')
    return {"codes": codes, "ver": ver or "?", "date": date, "n_req": n_req, "n_law": n_law}


def _guider_diff(a, b):
    ids = lambda o: [q[0] for c in o.values() for q in c["r"]]
    ia, ib = ids(a), ids(b)
    add_c, del_c = [c for c in b if c not in a], [c for c in a if c not in b]
    add_r, del_r = [x for x in ib if x not in set(ia)], [x for x in ia if x not in set(ib)]
    law = req = 0
    for c in b:
        if c not in a:
            continue
        old_l, old_r = dict((x[0], x[1]) for x in a[c]["l"]), dict((x[0], x[1]) for x in a[c]["r"])
        law += sum(1 for k, t in b[c]["l"] if old_l.get(k) != t)
        req += sum(1 for q, t in b[c]["r"] if q in old_r and old_r[q] != t)
    cut = lambda l: ", ".join(l[:12]) + ("…" if len(l) > 12 else "")
    rep = []
    if add_c:
        rep.append("Mã mới: " + ", ".join(add_c))
    if del_c:
        rep.append("Mã không còn: " + ", ".join(del_c))
    if add_r:
        rep.append("ID yêu cầu mới: " + cut(add_r))
    if del_r:
        rep.append("ID yêu cầu không còn: " + cut(del_r))
    if law:
        rep.append("Đã cập nhật %d hạng mục căn cứ pháp lý" % law)
    if req:
        rep.append("Đã cập nhật nội dung %d yêu cầu" % req)
    return rep or ["Không có thay đổi so với dữ liệu đang dùng"]


def _apply_guider(g):
    """Áp dữ liệu Guider (None = bản có sẵn) vào danh mục: cập nhật căn cứ pháp lý của từng lỗi, báo lỗi cần chọn lại mã."""
    codes = g["codes"] if g else BASE_CODES
    CODES.clear()
    CODES.update(copy.deepcopy(codes))
    notes = []
    for r, base in zip(RULE_LIST, BASE_LAW):
        new = []
        for c, k, t in base:
            it = next((x for x in CODES.get(c, {}).get("l", []) if x[0].startswith(k + ".")), None)
            if not it and g:
                notes.append("Lỗi %s: không còn hạng mục %s mục %s, giữ căn cứ cũ" % (r["id"], c, k))
            new.append([c, k, it[1] if it else t])
        r["l"] = new
        if g and not any(q[0] == r["q"] for q in CODES.get(r["c"], {}).get("r", [])):
            notes.append("Lỗi %s: không còn yêu cầu %s, cần chọn lại mã khi dùng" % (r["id"], r["q"]))
    if g:
        notes += ["Mã %s chưa có trong form Findings: cột Section, Category, Audit Item để trống và Summary không đếm" % c for c in CODES if c not in TPL_MAP]
        GUIDER.update(ver=g["ver"], date=g["date"], src="file", name=g.get("name", ""), sha=g.get("sha", ""), file=g.get("file", ""), changes=g.get("changes", []), notes=notes)
    else:
        GUIDER.update(ver="8.0.1", date="01/11/2026", src="builtin", name="", sha="", file="", changes=[], notes=[])


def _gpath():
    return os.path.join(WORK, "soat_ehs_guider.json")


def _is_guider(path):
    try:
        if os.path.getsize(path) > 30 * 1024 * 1024:
            return False
        with zipfile.ZipFile(path) as z:
            return "Guider chi tiết" in _nfc(z.read("xl/workbook.xml").decode("utf-8", "ignore"))
    except Exception:
        return False


def _search_roots():
    roots = [WORK] + (["/mnt"] if os.path.isdir("/mnt") else [])
    return list(dict.fromkeys(os.path.abspath(r) for r in roots))


def _found(pattern):
    hits = []
    for root in _search_roots():
        hits += glob.glob(os.path.join(root, "**", pattern), recursive=True)
    own = os.path.abspath(_dir())
    return sorted(set(os.path.abspath(h) for h in hits if not os.path.abspath(h).startswith(own + os.sep)), key=os.path.getmtime, reverse=True)


def _guider_files():
    return [f for f in _found("*.xlsx") if not os.path.basename(f).startswith(("Doi-chieu-Guider_", "Findings_")) and _is_guider(f)]


def load_guider(path=None):
    """Nạp file RBA Guider .xlsx (mặc định: file Guider mới nhất trong Project hoặc tin nhắn). Danh mục lỗi, ID yêu cầu và căn cứ pháp lý
    tự cập nhật theo file; file này cũng được dùng cho export_review(). Trả về các thay đổi so với dữ liệu đang dùng."""
    if path is None:
        fs = _guider_files()
        if not fs:
            raise FileNotFoundError("Không thấy file RBA Guider .xlsx nào. Hãy đính kèm file Guider vào tin nhắn hoặc thêm vào Project")
        path = fs[0]
    with open(path, "rb") as f:
        data = f.read()
    g = _parse_guider(data)
    keep = os.path.join(_dir(), "guider_dang_dung.xlsx")
    with open(keep, "wb") as f:
        f.write(data)
    g.update(name=os.path.basename(path), sha=hashlib.sha1(data).hexdigest(), file=keep, changes=_guider_diff(CODES, g["codes"]))
    _apply_guider(g)
    tmp = _gpath() + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(g, f, ensure_ascii=False)
    os.replace(tmp, _gpath())
    return dict(file=g["name"], version=g["ver"], law_date=g["date"], codes=len(g["codes"]), requirements=g["n_req"], law_items=g["n_law"],
                changes=g["changes"], notes=GUIDER["notes"])


def reset_guider():
    """Quay về dữ liệu RBA Guider 8.0.1 có sẵn trong công cụ."""
    for p in (_gpath(), os.path.join(_dir(), "guider_dang_dung.xlsx")):
        if os.path.exists(p):
            os.remove(p)
    _apply_guider(None)
    return "Đã quay về RBA Guider 8.0.1 có sẵn. Lưu ý: nếu file Guider vẫn còn trong Project, doctor() sẽ nạp lại file đó."


def guider_info():
    """Bản Guider đang dùng và các thay đổi đã nạp."""
    g = GUIDER
    head = "RBA Guider %s%s | %s" % (g["ver"], ", pháp lý chốt %s" % g["date"] if g["date"] else "", "bản có sẵn trong công cụ" if g["src"] == "builtin" else "nạp từ file %s" % g["name"])
    n_req = sum(len(c["r"]) for c in CODES.values())
    n_law = sum(len(c["l"]) for c in CODES.values())
    lines = [head, "%d mã, %d yêu cầu, %d hạng mục pháp lý" % (len(CODES), n_req, n_law)]
    if g["src"] == "file":
        lines += ["Thay đổi: " + "; ".join(g["changes"])] + (["Cần lưu ý:"] + ["- " + x for x in g["notes"]] if g["notes"] else [])
    return "\n".join(lines)


def _guider_boot():
    """Đọc lại bản Guider đã nạp trong cuộc trò chuyện này khi Python khởi động lại."""
    try:
        with open(_gpath(), encoding="utf-8") as f:
            g = json.load(f)
        if g.get("file") and not os.path.exists(g["file"]):
            g["file"] = ""
        _apply_guider(g)
    except Exception:
        pass


def _auto_load():
    """Tự nạp file Guider và sổ kinh nghiệm có trong Project hoặc tin nhắn, nếu là file mới hoặc đã thay đổi."""
    out = []
    try:
        fs = _guider_files()
        if fs and _sha_file(fs[0]) != GUIDER["sha"]:
            r = load_guider(fs[0])
            out.append("Đã nạp %s (Guider %s): %s" % (r["file"], r["version"], "; ".join(r["changes"])) + (". Cần lưu ý: " + "; ".join(r["notes"]) if r["notes"] else ""))
    except Exception as e:
        out.append("Không nạp được file Guider: %s" % e)
    seen = _lbook()["files"]
    for p in _found("*.json"):
        if os.path.basename(p).startswith("soat_ehs_") or seen.get(p) == _sha_file(p):
            continue
        try:
            with open(p, encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict) and d.get("kind") == "lessons":
                out.append("Đã nạp sổ kinh nghiệm %s: thêm %d kinh nghiệm" % (os.path.basename(p), _import_lessons(p)))
        except Exception:
            continue
    return out


