def catalog():
    """Danh mục lỗi nhìn thấy được trên ảnh và danh sách mã RBA. Đọc trước khi soát ảnh."""
    a = "\n".join("%s | %s | dấu hiệu: %s | %s %s | gợi ý %s | %s | %s" % (r["id"], r["t"], r["k"], r["c"], r["q"], r["v"], KINDS[r.get("kd", "violation")], r["z"]) for r in RULE_LIST)
    b = "\n".join("%s: %s" % (c, "; ".join(re.sub(r"^(\d+)\.\s*", r"\1 ", l[0]) for l in v["l"])) for c, v in CODES.items())
    gone = [r["id"] for r in RULE_LIST if not any(q[0] == r["q"] for q in CODES.get(r["c"], {}).get("r", []))]
    head = guider_info().split("\n")[0] + ("\nLỗi trong danh mục cần chọn lại mã vì ID yêu cầu không còn trong Guider: %s (dùng KHAC)" % ", ".join(gone) if gone else "")
    les = lessons()
    return "%s\n\nDANH MỤC LỖI (id | lỗi | dấu hiệu | mã RBA và ID yêu cầu | mức gợi ý | loại | cause)\n%s\n\nMÃ RBA VÀ HẠNG MỤC PHÁP LÝ (dùng khi rule = KHAC)\n%s%s" % (
        head, a, b, "\n\n" + les if les else "")


def lookup(code):
    """Yêu cầu và căn cứ pháp lý của một mã RBA theo file Guider."""
    if code.upper() not in CODES:
        raise ValueError("Không có mã %s trong RBA Guider %s" % (code.upper(), GUIDER["ver"]))
    v = CODES[code.upper()]
    t = TPL_MAP.get(code.upper()) or [v.get("g", ""), v.get("t", ""), "(mã chưa có trong form Findings)"]
    sc = lambda k: v["s"].get(k, "?")
    lines = ["%s | %s | %s | %s" % (code.upper(), t[0], t[1].replace("\n", " "), t[2]), "Thang điểm: Conformance %s, Minor %s, Major %s, Priority %s" % (sc("C"), sc("Mi"), sc("Ma"), sc("P")), "Yêu cầu:"]
    lines += ["- %s: %s" % (q[0], q[1]) for q in v["r"]]
    lines.append("Căn cứ pháp lý:")
    lines += ["- %s: %s" % (l[0], l[1]) for l in v["l"]]
    return "\n".join(lines)


def latest_images(limit=10):
    """Các ảnh mới nhất trong thư mục làm việc, mới nhất trước."""
    fs = [f for f in glob.glob(os.path.join(WORK, "*")) if re.search(r"\.(jpe?g|png|webp|heic|bmp)$", f, re.I) and not os.path.basename(f).startswith(("xem_truoc_", "Bao-cao-EHS_"))]
    return sorted(fs, key=os.path.getmtime, reverse=True)[:limit]


def doctor():
    """Kiểm tra Pillow, phông tiếng Việt, quyền ghi file; tự nạp file Guider và sổ kinh nghiệm mới có trong Project hoặc tin nhắn."""
    p = os.path.join(_dir(), "ping.txt")
    with open(p, "w") as f:
        f.write("ok")
    os.remove(p)
    notes = _auto_load()
    line = "OK | thư mục %s | phông %s | RBA Guider %s (%s) | %d lỗi, %d mã | %d kinh nghiệm | %d ảnh đang có" % (
        WORK, os.path.basename(_font(20).path), GUIDER["ver"], "có sẵn" if GUIDER["src"] == "builtin" else "file " + GUIDER["name"],
        len(RULE_LIST), len(CODES), len(_lbook()["items"]), len(_load()["photos"]))
    return "\n".join([line] + notes)


# ---------- Phiên soát ----------
def start(vendor=None, auditor=None, date=None, subsidiary=None, reset=False):
    """Đặt thông tin audit. reset=True xóa toàn bộ phiên trước."""
    st = None
    if reset and os.path.exists(_state_path()):
        os.remove(_state_path())
    st = _load()
    m = st["meta"]
    for k, v in (("vendor", vendor), ("auditor", auditor), ("subsidiary", subsidiary)):
        if v is not None:
            m[k] = str(v).strip()
    if date:
        m["date"] = _iso(date)
    _save(st)
    return dict(m)


def _resolve(f, a):
    r = RULES.get(a.get("rule"))
    if r:
        f.update(rule=r["id"], code=r["c"], req=r["q"], law=" | ".join(dict.fromkeys(l[2] for l in r["l"])))
        c, k = (r["l"][0][0], r["l"][0][1]) if r["l"] else ("", "")
        it = next((l for l in CODES.get(c, {}).get("l", []) if l[0].startswith(k + ".")), None)
        f["item"] = "%s mục %s" % (c, it[0]) if it else ""
    else:
        code = str(a.get("rba_code") or "").upper()
        code = code if code in CODES else ""
        k = re.sub(r"\D", "", str(a.get("law_item") or "")).zfill(2)
        it = next((l for l in CODES[code]["l"] if l[0].startswith(k + ".")), None) if code else None
        q = str(a.get("req_id") or "")
        req = (q if any(x[0] == q for x in CODES[code]["r"]) else CODES[code]["r"][0][0]) if code else ""
        f.update(rule="", code=code, req=req, law=it[1] if it else "", item="%s mục %s" % (code, it[0]) if it else "")
    return r


def _make(a, warns):
    s = _box(a.get("box"))
    if s is None:
        s = {"x": 0.05, "y": 0.05, "w": 0.9, "h": 0.9}
        warns.append("Một lỗi có khung không hợp lệ, đã đặt tạm toàn ảnh: %s" % str(a.get("title_vi"))[:50])
    f = {"s": s, "title_vi": str(a.get("title_vi") or "").strip(), "title_en": str(a.get("title_en") or "").strip(), "ev": str(a.get("evidence") or "").strip(),
         "fix_now": str(a.get("fix_now") or "").strip(), "fix_root": str(a.get("fix_root") or "").strip(), "plan_en": str(a.get("plan_en") or "").strip(), "due": "", "ok": False}
    r = _resolve(f, a)
    if not f["title_vi"] and r:
        f["title_vi"] = r["t"]
    f["fix_now"] = f["fix_now"] or (r["n"] if r else "")
    f["fix_root"] = f["fix_root"] or (r["x"] if r else "")
    f["sev"] = a.get("severity") if a.get("severity") in SEV else (r["v"] if r else "Minor")
    f["cause"] = a.get("cause") if a.get("cause") in CAUSE else (r["z"] if r else "Administrative")
    f["mand"] = a.get("mandatory") if isinstance(a.get("mandatory"), bool) else f["sev"] == "Priority"
    f["kind"] = a.get("kind") if a.get("kind") in KINDS else (r.get("kd", "violation") if r else "violation")
    try:
        f["conf"] = int(a.get("confidence"))
    except (TypeError, ValueError):
        f["conf"] = None
    if not f["code"]:
        warns.append("Lỗi chưa có mã RBA hợp lệ: %s" % f["title_vi"][:50])
    return f


def _qualifies(f):
    if f["conf"] is not None and f["conf"] < MIN_CONF:
        return "chưa đủ chắc chắn (%d%%)" % f["conf"]
    return ""


def add_finding(photo_no, finding):
    """Người đánh giá chủ động thêm một lỗi vào ảnh. Không áp tiêu chí lọc. Ghi vào sổ kinh nghiệm là lỗi AI bỏ sót."""
    st = _load()
    p = st["photos"][int(photo_no) - 1]
    warns = []
    f = _make(finding, warns)
    f["src"] = "manual"
    p["findings"].append(f)
    learned = _learn(p, f)
    _save(st)
    return dict(preview=show(int(photo_no))[0], summary=summary(), warnings=warns, learned=learned)


def _cell_image(p, items):
    """Ảnh cho ô Problem Photo 1: luôn lấp kín ô kích thước mặc định, lấy vùng lỗi làm tâm nhưng giữ đủ hiện trạng xung quanh."""
    S = 4
    W, H = round(CELL_WPT * 4 / 3 * S), round(CELL_HPT * 4 / 3 * S)
    A = W / H
    im = _photo(p)
    iw, ih = im.size
    ux0 = min(f["s"]["x"] for _, f in items) * iw
    uy0 = min(f["s"]["y"] for _, f in items) * ih
    ux1 = max(f["s"]["x"] + f["s"]["w"] for _, f in items) * iw
    uy1 = max(f["s"]["y"] + f["s"]["h"] for _, f in items) * ih
    max_w = ih * A if iw / ih > A else iw
    cw = min(max_w, max((ux1 - ux0) * 2.2, (uy1 - uy0) * 2.2 * A, max_w * 0.55))
    ch = cw / A
    cx = min(max((ux0 + ux1) / 2 - cw / 2, 0), iw - cw)
    cy = min(max((uy0 + uy1) / 2 - ch / 2, 0), ih - ch)
    crop = im.crop((round(cx), round(cy), round(cx + cw), round(cy + ch))).resize((W, H), Image.LANCZOS)
    moved = [(k, dict(f, s={"x": (f["s"]["x"] * iw - cx) / cw, "y": (f["s"]["y"] * ih - cy) / ch, "w": f["s"]["w"] * iw / cw, "h": f["s"]["h"] * ih / ch})) for k, f in items]
    return _marks(crop, moved, max(3, W / 180), W / 24)


def _numbered_text(fs, get, multi):
    return "\n".join("%d. %s%s" % (k, "(%s) " % f["code"] if multi and f["code"] else "", get(f).strip()) for k, f in enumerate(fs, 1) if get(f).strip())


def add_photo(path, findings, area_vi="", area_en="", scene="", compliant=None, verify=None):
    """Thêm một ảnh kèm lỗi đã soát (vi phạm và mối nguy tiềm ẩn). Lỗi có confidence dưới 70 bị loại, nằm trong excluded."""
    if not os.path.exists(path):
        hits = glob.glob(os.path.join(WORK, "**", os.path.basename(path)), recursive=True)
        if not hits:
            raise FileNotFoundError("Không thấy ảnh %s trong %s" % (path, WORK))
        path = hits[0]
    st = _load()
    im = ImageOps.exif_transpose(Image.open(path)).convert("RGB")
    im.thumbnail((2400, 2400), Image.LANCZOS)
    pid = 1 + max([p["id"] for p in st["photos"]] + [0])
    file = os.path.join(_dir(), "anh_%03d.jpg" % pid)
    im.save(file, quality=90)
    warns, keep, excluded = [], [], []
    for a in findings:
        if isinstance(a, dict):
            f = _make(a, warns)
            f["src"], f["ai0"] = "ai", _snap(f)
            why = _qualifies(f)
            if why:
                excluded.append("%s: %s" % (f["title_vi"], why))
            else:
                keep.append(f)
    fs = _tidy(keep)
    learned = _use_lessons(area_vi, fs, excluded)
    p = {"id": pid, "file": file, "name": os.path.basename(path), "area_vi": area_vi.strip(), "area_en": area_en.strip(), "scene": scene, "compliant": compliant or [], "verify": verify or [],
         "excluded": excluded, "findings": fs}
    st["photos"].append(p)
    _save(st)
    n = len(st["photos"])
    return dict(photo_no=n, preview=show(n)[0], summary=summary(), warnings=warns, excluded=excluded, learned=learned)


def show(photo_no=None):
    """Tạo ảnh xem trước có lưới ô A1 để chỉ vùng bằng lời. Số trên ảnh đánh từ 1 cho mỗi ảnh."""
    st = _load()
    out = []
    for i, p in enumerate(st["photos"], 1):
        if photo_no and i != int(photo_no):
            continue
        im = _grid(_fit(_photo(p), 1400, 1000))
        im = _marks(im, list(enumerate(p["findings"], 1)), max(2, im.width / 480), max(13, im.width / 62))
        path = os.path.join(WORK, "xem_truoc_anh_%d.jpg" % i)
        im.save(path, quality=88)
        out.append(path)
    return out


def summary():
    """Danh sách lỗi hiện tại. Số lỗi có dạng ảnh.lỗi, trùng số trên ảnh."""
    st = _load()
    lines = []
    for i, p in enumerate(st["photos"], 1):
        if not p["findings"]:
            lines.append("Ảnh %d | không có lỗi đạt tiêu chí báo cáo" % i)
        for k, f in enumerate(p["findings"], 1):
            lines.append("%d.%d | %s | %s | %s%s | %s | %s | Hạng mục Guider: %s, %s | Căn cứ: %s" % (
                i, k, KINDS.get(f.get("kind"), "Vi phạm"), f["sev"], f["cause"], " | mandatory" if f["mand"] else "", "đã xác nhận" if f["ok"] else "chờ xác nhận",
                f["title_vi"], f["req"] or "chưa có mã", f.get("item") or f["code"], f["law"] or "chưa gán"))
    return "\n".join(lines) or "Chưa có ảnh nào."


def update(ref, cells=None, box=None, **kw):
    """Sửa lỗi ref dạng "ảnh.lỗi". cells="C3:E5" hoặc box=[x1,y1,x2,y2]; kw: title_vi, title_en, evidence, fix_now, fix_root, plan_en, severity, kind, cause, mandatory, rule, rba_code, law_item, req_id, due, confirmed."""
    st = _load()
    pi, p, f = _find(st, ref)
    before = _snap(f)
    if cells:
        f["s"] = cells_to_box(cells)
    if box:
        b = _box(box)
        if not b:
            raise ValueError("Khung không hợp lệ")
        f["s"] = b
    if "rule" in kw or "rba_code" in kw:
        r = _resolve(f, kw)
        if r and "title_vi" not in kw:
            f["title_vi"] = r["t"]
    names = {"title_vi": "title_vi", "title_en": "title_en", "evidence": "ev", "fix_now": "fix_now", "fix_root": "fix_root", "plan_en": "plan_en"}
    for k, v in kw.items():
        if k in names:
            f[names[k]] = str(v).strip()
    if kw.get("severity") in SEV:
        f["sev"] = kw["severity"]
    if kw.get("cause") in CAUSE:
        f["cause"] = kw["cause"]
    if isinstance(kw.get("mandatory"), bool):
        f["mand"] = kw["mandatory"]
    if kw.get("due"):
        f["due"] = _iso(kw["due"])
    if isinstance(kw.get("confirmed"), bool):
        f["ok"] = kw["confirmed"]
    if kw.get("kind") in KINDS:
        f["kind"] = kw["kind"]
    if _snap(f) != before:
        f["learned"] = False
    msg = _learn(p, f) if f["ok"] else ""
    _save(st)
    if msg:
        print(msg)
    return show(pi)


def remove(ref, reason=None):
    """Xóa lỗi ref dạng "ảnh.lỗi". Các số sau trong cùng ảnh sẽ dồn lại.
    reason khi xóa đề xuất của AI: "reject" (không phải lỗi) hoặc "unclear" (ảnh không đủ rõ) được ghi vào sổ kinh nghiệm;
    "dup" (sai vị trí hoặc trùng) thì không ghi."""
    st = _load()
    pi, p, f = _find(st, ref)
    p["findings"].remove(f)
    if reason in ("reject", "unclear") and f.get("src") == "ai" and not f.get("ok") and f["title_vi"].strip():
        _ladd({"t": reason, "title": f["title_vi"].strip(), "area": p.get("area_vi", ""), "to": _snap(f)})
        print("Đã ghi vào sổ kinh nghiệm: %s" % LTYPE[reason].lower())
    _save(st)
    return show(pi)


def merge(a, b):
    """Gộp lỗi b vào lỗi a, cả hai dạng "ảnh.lỗi" và cùng một ảnh."""
    st = _load()
    pa, p, fa = _find(st, a)
    pb, _, fb = _find(st, b)
    if pa != pb:
        raise ValueError("Hai lỗi nằm ở hai ảnh khác nhau")
    _merge_into(fa, fb)
    p["findings"].remove(fb)
    _save(st)
    return show(pa)


def split_overlaps(photo_no):
    """Tự cắt các vùng đang chồng lên nhau trên một ảnh."""
    st = _load()
    _trim(st["photos"][photo_no - 1]["findings"])
    _save(st)
    return show(photo_no)


def confirm_all():
    """Đánh dấu mọi lỗi là đã được người đánh giá xác nhận."""
    st = _load()
    n = 0
    for _, _, p, f in _numbered(st):
        f["ok"] = True
        n += _learn(p, f).startswith("Đã ghi")
    _save(st)
    return summary() + ("\nĐã ghi %d kinh nghiệm mới từ các lỗi bạn đã sửa." % n if n else "")


# ---------- Xuất file ----------
def _safe(s):
    s = unicodedata.normalize("NFD", str(s or "audit"))
    s = "".join(c for c in s if not unicodedata.combining(c)).replace("đ", "d").replace("Đ", "D")
    return re.sub(r"[^A-Za-z0-9_-]+", "-", s).strip("-")[:60] or "audit"


def export_images():
    """Xuất mỗi ảnh có lỗi một file JPG kèm lỗi và cách khắc phục. Trả về danh sách đường dẫn."""
    st = _load()
    out = []
    for i, p in enumerate(st["photos"], 1):
        items = list(enumerate(p["findings"], 1))
        if items:
            path = os.path.join(WORK, "Bao-cao-EHS_%02d_%s.jpg" % (i, _safe(p["area_vi"] or p["name"])))
            _report(st, p, items).save(path, quality=92)
            out.append(path)
    return out


def _esc(v):
    v = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", str("" if v is None else v))
    return v.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def _t(ref, sty, v):
    return '<c r="%s" s="%s"/>' % (ref, sty) if v in ("", None) else '<c r="%s" s="%s" t="inlineStr"><is><t xml:space="preserve">%s</t></is></c>' % (ref, sty, _esc(v))


def _both(en, vi):
    en, vi = (en or "").strip(), (vi or "").strip()
    return "%s\n%s" % (en, vi) if en and en != vi else vi


def _lines(t, w):
    return sum(max(1, -(-len(l) // w)) for l in str(t or "").split("\n"))


def _plan_vi(f):
    return " ".join(x for x in (_sentence(f["fix_now"]), _sentence(f["fix_root"])) if x)


def export_findings():
    """Điền mẫu Findings: mỗi ảnh một dòng, ảnh nằm vừa ô Problem Photo 1, lỗi đánh số trùng số trên ảnh. Giữ nguyên macro và sheet Summary."""
    st = _load()
    m = st["meta"]
    groups = [(i, p) for i, p in enumerate(st["photos"], 1) if p["findings"]]
    if not groups:
        raise ValueError("Chưa có lỗi nào để xuất")
    src = zipfile.ZipFile(__import__("io").BytesIO(base64.b64decode(TPL_B64)))
    parts = {n: src.read(n) for n in src.namelist()}
    rows, pics, rels, media = [], [], [], {}
    for no, (i, p) in enumerate(groups, 1):
        r = 6 + no
        fs = p["findings"]
        rank = lambda f: SEV.index(f["sev"]) if f["sev"] in SEV else 9
        main = next((f["code"] for f in sorted(fs, key=rank) if f["code"]), "")
        multi = any(f["code"] and f["code"] != main for f in fs)
        B, C, E = TPL_MAP.get(main, ["", "", ""])
        D = main
        en_g, vi_g = _numbered_text(fs, lambda f: f["title_en"], multi), _numbered_text(fs, lambda f: f["title_vi"], multi)
        en_m, vi_m = _numbered_text(fs, lambda f: f["plan_en"], multi), _numbered_text(fs, lambda f: _sentence(f["fix_root"] or f["fix_now"]), multi)
        G = "%s\n\n%s" % (en_g, vi_g) if en_g else vi_g
        M = "%s\n\n%s" % (en_m, vi_m) if en_m else vi_m
        area = _both(p["area_en"], p["area_vi"]) or "Site\nHiện trường"
        cause = "Facility" if any(f["cause"] == "Facility" for f in fs) else "Administrative"
        mand = any(f["mand"] for f in fs)
        start = datetime.date.fromisoformat(m["date"])
        due = min(f["due"] or (start + datetime.timedelta(days=DUE.get(f["sev"], 30))).isoformat() for f in fs)
        pt = min(409, max(CELL_HPT, 6 + 16 * max(_lines(G, 70), _lines(M, 35), _lines(area, 15), _lines(E, 32), _lines(B, 35), _lines(D, 8))))
        cs = 31 if "\n" in C else (4 if C == "Environment" else 9)
        rows.append('<row r="%d" spans="1:19" ht="%.1f" customHeight="1"><c r="A%d" s="4"><v>%d</v></c>' % (r, pt, r, no)
                    + _t("B%d" % r, 31, B) + _t("C%d" % r, cs, C) + _t("D%d" % r, 31, D) + _t("E%d" % r, 7, E) + _t("F%d" % r, 31, area) + _t("G%d" % r, 32, G)
                    + _t("H%d" % r, 78, cause) + _t("I%d" % r, 48, "mandatory" if mand else "")
                    + '<c r="J%d" s="4"/><c r="K%d" s="4"/><c r="L%d" s="1"/>' % (r, r, r) + _t("M%d" % r, 2, M) + _t("N%d" % r, 4, _vn(due))
                    + "".join('<c r="%s%d" s="1"/>' % (c, r) for c in "OPQRS") + "</row>")
        buf = __import__("io").BytesIO()
        _cell_image(p, list(enumerate(fs, 1))).save(buf, "JPEG", quality=88)
        media["xl/media/image%d.jpeg" % no] = buf.getvalue()
        cx, cy = int(CELL_WPT * 12700), int(CELL_HPT * 12700)
        rels.append('<Relationship Id="rId%d" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/image%d.jpeg"/>' % (no, no))
        # Ảnh phủ đúng ô J theo chiều ngang và cao đúng 150 pt; dòng cao hơn do nhiều chữ thì ảnh vẫn giữ kích thước mặc định.
        pics.append('<xdr:twoCellAnchor editAs="oneCell"><xdr:from><xdr:col>9</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>%d</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from>'
                    '<xdr:to><xdr:col>10</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>%d</xdr:row><xdr:rowOff>%d</xdr:rowOff></xdr:to>'
                    '<xdr:pic><xdr:nvPicPr><xdr:cNvPr id="%d" name="Problem photo %d"/><xdr:cNvPicPr><a:picLocks noChangeAspect="1"/></xdr:cNvPicPr></xdr:nvPicPr>'
                    '<xdr:blipFill><a:blip r:embed="rId%d"/><a:stretch><a:fillRect/></a:stretch></xdr:blipFill>'
                    '<xdr:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="%d" cy="%d"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr></xdr:pic><xdr:clientData/></xdr:twoCellAnchor>'
                    % (r - 1, r - 1, cy, no + 1, no, no, cx, cy))
    last = max(19, 6 + len(groups))
    sh = parts["xl/worksheets/sheet2.xml"].decode("utf-8")
    for k, v in (("__C1__", m["subsidiary"]), ("__C2__", m["vendor"]), ("__C3__", _vn(m["date"])), ("__C4__", m["auditor"])):
        sh = sh.replace(k, _esc(v))
    sh = sh.replace("</sheetData>", "".join(rows) + "</sheetData>").replace("__DV__", str(max(47, last))).replace("__LAST__", str(last))
    parts["xl/worksheets/sheet2.xml"] = sh.encode("utf-8")
    parts["xl/workbook.xml"] = parts["xl/workbook.xml"].decode("utf-8").replace("__LAST__", str(last)).encode("utf-8")
    parts["xl/drawings/drawing1.xml"] = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">%s</xdr:wsDr>' % "".join(pics)).encode("utf-8")
    parts["xl/drawings/_rels/drawing1.xml.rels"] = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">%s</Relationships>' % "".join(rels)).encode("utf-8")
    parts.update(media)
    base = os.path.join(WORK, "Findings_%s_%s" % (_safe(m["vendor"]), m["date"]))
    with zipfile.ZipFile(base + ".xlsm", "w", zipfile.ZIP_DEFLATED) as z:
        for n, b in parts.items():
            z.writestr(n, b)
    with zipfile.ZipFile(base + ".zip", "w", zipfile.ZIP_DEFLATED) as z:
        z.write(base + ".xlsm", os.path.basename(base) + ".xlsm")
    allf = [f for _, p in groups for f in p["findings"]]
    warn = []
    if sum(1 for f in allf if not f["ok"]):
        warn.append("%d lỗi chưa được xác nhận" % sum(1 for f in allf if not f["ok"]))
    if sum(1 for f in allf if not f["code"]):
        warn.append("%d lỗi chưa có mã RBA nên Summary chưa đếm" % sum(1 for f in allf if not f["code"]))
    if sum(1 for f in allf if not f["title_en"] or not f["plan_en"]):
        warn.append("%d lỗi thiếu tiếng Anh" % sum(1 for f in allf if not f["title_en"] or not f["plan_en"]))
    if not m["auditor"]:
        warn.append("chưa có tên Auditor")
    if last > 91:
        warn.append("quá 85 dòng, công thức Summary của mẫu có thể đếm thiếu")
    newc = sorted(set(f["code"] for f in allf if f["code"] and f["code"] not in TPL_MAP))
    if newc:
        warn.append("mã %s không có trong form Findings nên Summary không đếm" % ", ".join(newc))
    new = _new_lessons()
    les = export_lessons()["file"] if new else ""
    return dict(xlsm=base + ".xlsm", zip=base + ".zip", rows=len(groups), warnings=warn, lessons=les, new_lessons=new)


def export_review():
    """Đối chiếu kết quả soát sang file Guider đang dùng (file đã nạp, nếu không thì bản 8.0.1 có sẵn) và lưu thành file mới:
    - Đánh giá 41 mã: kết quả (mức nặng nhất), phát hiện, bằng chứng, hạn, ngày, người đánh giá, ghi chú.
    - CAP: nguyên nhân gốc, hành động khắc phục, ngày mở, hạn hoàn thành, trạng thái nếu đang trống.
    - Guider chi tiết: đánh giá chi tiết và ghi chú cho từng ID yêu cầu.
    Số lỗi dạng No.điểm theo file Findings (No. là số dòng trong Findings). Công thức của file giữ nguyên và tự tính lại khi mở."""
    st = _load()
    m = st["meta"]
    groups = [(i, p) for i, p in enumerate(st["photos"], 1) if p["findings"]]
    if not groups:
        raise ValueError("Chưa có lỗi nào để đối chiếu")
    warn = []
    if GUIDER["file"] and os.path.exists(GUIDER["file"]):
        with open(GUIDER["file"], "rb") as f:
            bk = _Book(f.read())
    else:
        if GUIDER["src"] == "file":
            warn.append("không còn file Guider đã nạp, dùng file RBA Guider 8.0.1 có sẵn")
        bk = _Book(base64.b64decode(_GUIDER_B64))
    start = datetime.date.fromisoformat(m["date"])
    ser = (start - datetime.date(1899, 12, 30)).days
    serial = lambda iso: (datetime.date.fromisoformat(iso) - datetime.date(1899, 12, 30)).days if iso else ""
    allx = [(f, "%d.%d" % (no, k), no, i) for no, (i, p) in enumerate(groups, 1) for k, f in enumerate(p["findings"], 1)]

    def by(key):
        d = {}
        for x in allx:
            if key(x[0]):
                d.setdefault(key(x[0]), []).append(x)
        return d
    by_code, by_req = by(lambda f: f["code"]), by(lambda f: f["req"])
    rank = lambda s: SEV.index(s) if s in SEV else 9
    worst = lambda l: sorted([x[0]["sev"] for x in l if x[0]["sev"]], key=rank)[0] if any(x[0]["sev"] for x in l) else "Minor"
    due = lambda l: min(x[0]["due"] or (start + datetime.timedelta(days=DUE.get(x[0]["sev"], 30))).isoformat() for x in l)
    finds = lambda l: "\n".join("%s %s (%s, %s)" % (x[1], x[0]["title_vi"].strip(), x[0]["sev"] or "chưa xác định", KINDS.get(x[0].get("kind"), "Vi phạm")) for x in l)
    acts = lambda l: "\n".join("%s %s" % (x[1], _plan_vi(x[0])) for x in l)

    def causes(l):
        out = []
        for c, lab in (("Facility", "Facility (thiết bị, hạ tầng chưa đạt)"), ("Administrative", "Administrative (quản lý, sắp xếp, vận hành)")):
            refs = [x[1] for x in l if (x[0]["cause"] or "Administrative") == c]
            if refs:
                out.append("%s: %s" % (lab, ", ".join(refs)))
        return "\n".join(out)

    sh = bk.sheet("Đánh giá 41 mã")
    H = sh.header("Mã RBA") if sh else None
    if not H:
        raise ValueError('Không thấy sheet "Đánh giá 41 mã" hoặc dòng tiêu đề của sheet này trong file Guider')
    hr, C = H
    code_row, miss = {}, []
    for n in sh.nums:
        if n > hr and sh.get(C("mã rba"), n).strip():
            code_row[sh.get(C("mã rba"), n).strip()] = n
    for code, l in by_code.items():
        n = code_row.get(code)
        if not n:
            miss.append(code)
            continue
        nv = sum(1 for x in l if x[0].get("kind", "violation") == "violation")
        rows = ", ".join(str(r) for r in dict.fromkeys(x[2] for x in l))
        sh.put(C("kết quả đánh giá"), n, worst(l))
        sh.put(C("hạn hoàn thành"), n, serial(due(l)), True)
        sh.put(C("phát hiện"), n, finds(l))
        sh.put(C("bằng chứng"), n, re.sub(r"\s+", " ", "Ảnh hiện trường trong file Findings %s ngày %s, dòng %s" % (m["vendor"], _vn(m["date"]), rows)))
        sh.put(C("ngày đánh giá"), n, ser, True)
        sh.put(C("người đánh giá"), n, m["auditor"])
        sh.put(C("ghi chú"), n, "Soát ảnh: %d lỗi (%d vi phạm, %d mối nguy tiềm ẩn). Số lỗi dạng No.điểm theo file Findings." % (len(l), nv, len(l) - nv))
    n_cap = n_req = 0
    cap = bk.sheet("CAP")
    H = cap.header("Mã RBA") if cap else None
    if H:
        hr, C = H
        inv = {n: c for c, n in code_row.items()}
        for n in cap.nums:
            if n <= hr:
                continue
            fm = re.search(r"!\$?[A-Z]+\$?(\d+)", cap.formula(C("mã rba"), n))
            code = inv.get(int(fm.group(1))) if fm else cap.get(C("mã rba"), n).strip()
            l = by_code.get(code)
            if not l:
                continue
            cap.put(C("nguyên nhân gốc"), n, causes(l))
            cap.put(C("hành động khắc phục"), n, acts(l))
            cap.put(C("ngày mở"), n, ser, True)
            cap.put(C("hạn hoàn thành"), n, serial(due(l)), True)
            if C("trạng thái") and not cap.get(C("trạng thái"), n).strip():
                cap.put(C("trạng thái"), n, "Chưa bắt đầu")
            n_cap += 1
    else:
        warn.append('không thấy sheet "CAP"')
    gd = bk.sheet("Guider chi tiết")
    H = gd.header("ID yêu cầu") if gd else None
    if H:
        hr, C = H
        done = set()
        for n in gd.nums:
            if n <= hr:
                continue
            q = gd.get(C("id yêu cầu"), n).strip()
            l = by_req.get(q)
            if not l:
                continue
            gd.put(C("đánh giá chi tiết"), n, worst(l))
            gd.put(C("ghi chú"), n, finds(l))
            gd.put(C("ngày cập nhật"), n, ser, True)
            done.add(q)
            n_req += 1
        lost = [q for q in by_req if q not in done]
        if lost:
            warn.append("ID yêu cầu %s không có trong sheet Guider chi tiết của Guider %s, hãy đổi mã các lỗi %s bằng update" % (
                ", ".join(lost), GUIDER["ver"], ", ".join(x[1] for q in lost for x in by_req[q])))
    path = os.path.join(WORK, "Doi-chieu-Guider_%s_%s.xlsx" % (_safe(m["vendor"]), m["date"]))
    with open(path, "wb") as f:
        f.write(bk.save())
    if miss:
        warn.append("không thấy mã %s trong sheet Đánh giá 41 mã" % ", ".join(miss))
    allf = [x[0] for x in allx]
    if any(not f["code"] for f in allf):
        warn.append("%d lỗi chưa có mã RBA nên không được đối chiếu" % sum(1 for f in allf if not f["code"]))
    if any(not f["ok"] for f in allf):
        warn.append("%d lỗi chưa được xác nhận" % sum(1 for f in allf if not f["ok"]))
    if not m["auditor"]:
        warn.append("chưa có tên người đánh giá")
    moved = ["No.%d là ảnh %d" % (no, i) for no, (i, _) in enumerate(groups, 1) if no != i]
    return dict(xlsx=path, guider=GUIDER["ver"], codes=len(by_code) - len(miss), cap_rows=n_cap, requirements=n_req,
                numbering="Số lỗi dạng No.điểm theo file Findings" + (" (%s)" % ", ".join(moved) if moved else ", trùng số ảnh.lỗi"), warnings=warn)


_guider_boot()


